SELECT t.rec_id AS record_id,t."供应商" AS "供应商",t."关闭依据" AS "关闭依据",t."工厂" AS "工厂",t."操作人" AS "操作人",t."整改措施" AS "整改措施",t."更新时间" AS "更新时间",(t."状态").name AS "状态",t."计划完成日期" AS "计划完成日期",t."责任人" AS "责任人",t."问题主题" AS "问题主题",t."问题编号" AS "问题编号",(t."风险等级").name AS "风险等级",s.rec_id AS supplier_id,s."供应商名称" AS supplier_name,s."国家" AS supplier_country,(s."推广阶段").name AS supplier_stage FROM "SupplierIssues" AS t LEFT JOIN "Suppliers" AS s ON t."供应商" @> ARRAY[s.rec_id] INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|issue.read|%')) ORDER BY t.rec_id ASC LIMIT 500 OFFSET $1